        menuList.appendChild(mainTools);

      } else {
        root.classList.remove("edit-mode");
        pdoc.querySelectorAll(`#${ID} .toggle-btn.edit-tools-wrap`).forEach((btn) => btn.classList.remove("edit-tools-wrap"));
        toastr.info("已退出编辑模式并保存");
